fn unhex(s: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    for (i, chunk) in s.as_bytes().chunks(2).enumerate() {
        let hi = (chunk[0] as char).to_digit(16).expect("hex");
        let lo = (chunk[1] as char).to_digit(16).expect("hex");
        out[i] = (hi * 16 + lo) as u8;
    }
    out
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[test]
fn mldsa65_public_keys_are_deterministic_from_the_seed() {
    use ml_dsa::{Keypair as _, MlDsa65, Signer as _, SigningKey, Verifier as _};

    for (seed_hex, pk_hex) in KAT {
        let seed = unhex(seed_hex);
        let sk = SigningKey::<MlDsa65>::from_seed(&ml_dsa::Seed::from(seed));
        let mut vk = [0u8; 1952];
        vk.copy_from_slice(sk.verifying_key().encode().as_slice());
        assert_eq!(hex(&vk), *pk_hex);

        // The pinned key is not just any bytes: it verifies a fresh
        // signature made from the same seed.
        let sig = sk.sign(b"kirino-session mldsa65 kat");
        assert!(sk
            .verifying_key()
            .verify(b"kirino-session mldsa65 kat", &sig)
            .is_ok());
    }
}

#[test]
fn mldsa65_distinct_seeds_derive_distinct_keys() {
    use ml_dsa::{MlDsa65, SigningKey};

    // Cheap negative control on the KAT lane itself: two different seeds
    // must not collide on one key (if they did, determinism above would
    // be pinning a broken generator).
    let a = SigningKey::<MlDsa65>::from_seed(&ml_dsa::Seed::from(unhex(KAT[0].0)));
    let b = SigningKey::<MlDsa65>::from_seed(&ml_dsa::Seed::from(unhex(KAT[1].0)));
    assert_ne!(KAT[0].1, KAT[1].1);
    let _ = (a, b); // keygen itself must not panic
}
